-- Source: MotherDuck thyroid_canonical_publication_v1_0.manuscript_workspace.ete_manuscript_analytic_v4
-- Captured: 2026-05-06 for THY-19 BQ migration

CREATE VIEW manuscript_workspace.ete_manuscript_analytic_v4 AS WITH q_open AS (SELECT DISTINCT CAST(research_id AS VARCHAR) AS research_id FROM manuscript_workspace.cpm_ete_self_contradiction_queue_v1 WHERE (status = 'awaiting_manual_review')), pm AS (SELECT research_id, ete_grade_clean, ete_grade, ete_grade_source, ete_grade_adjudicated, ete_adjudicated_flag FROM main.canonical_patient_master)SELECT v3.*, pm.ete_grade_clean AS pm_ete_grade_clean, pm.ete_grade_source AS pm_ete_grade_source, pm.ete_grade_adjudicated AS pm_ete_grade_adjudicated, pm.ete_adjudicated_flag AS pm_ete_adjudicated_flag, CASE  WHEN (((v3.ete_grade_final_v3 IS NOT NULL) AND (v3.ete_grade_final_v3 != 'unspec_remaining'))) THEN (v3.ete_grade_final_v3) WHEN ((pm.ete_grade_clean IN ('gross', 'microscopic', 'none'))) THEN (pm.ete_grade_clean) WHEN ((v3.ete_grade_final_v3 = 'unspec_remaining')) THEN ('unspec_remaining') WHEN ((pm.ete_grade_clean = 'indeterminate')) THEN ('indeterminate') ELSE NULL END AS ete_grade_final_v4, CASE  WHEN (((v3.ete_grade_final_v3 IS NOT NULL) AND (v3.ete_grade_final_v3 != 'unspec_remaining'))) THEN (v3.ete_grade_source_v3) WHEN ((pm.ete_grade_clean IN ('gross', 'microscopic', 'none'))) THEN ('patient_master_clean') WHEN ((v3.ete_grade_final_v3 = 'unspec_remaining')) THEN ('unresolved') WHEN ((pm.ete_grade_clean = 'indeterminate')) THEN ('patient_master_indeterminate') ELSE NULL END AS ete_grade_source_v4, ((pm.ete_grade IS NOT NULL) AND (pm.ete_grade_clean IS NOT NULL) AND (pm.ete_grade NOT IN ('true', 'false', 'absent', 'present_ungraded')) AND (pm.ete_grade_clean NOT IN ('indeterminate')) AND (pm.ete_grade != pm.ete_grade_clean)) AS ete_grade_pm_disagreement_flag, EXISTS(SELECT 1 FROM q_open AS q WHERE (q.research_id = CAST(v3.research_id AS VARCHAR))) AS ete_self_contradiction_open_flag, ((COALESCE(CASE  WHEN (((v3.ete_grade_final_v3 IS NOT NULL) AND (v3.ete_grade_final_v3 != 'unspec_remaining'))) THEN (v3.ete_grade_final_v3) ELSE pm.ete_grade_clean END, v3.ete_norm) IS NOT NULL) AND (v3.surgery_episode_id_global IS NOT NULL) AND (v3.size_greatest_dimension_cm_trusted IS NOT NULL) AND (v3.primary_histology_trusted IS NOT NULL) AND (v3.primary_histology_trusted NOT IN ('NIFTP', 'FTUMP', 'follicular adenoma', 'atypical follicular / hurthle neoplasm', 'uncertain malignant potential (non-FTUMP)'))) AS analytic_eligible_v4 FROM manuscript_workspace.ete_manuscript_analytic_v3 AS v3 LEFT JOIN pm ON ((pm.research_id = v3.research_id));
